const runId = Math.random().toString(36).slice(2, 8);
const closed = [];
for (const issue of tool("list_issues", {})) {
  if (tool("ask_human", { question: "[" + runId + "] close #" + issue.id + " " + issue.title + "?" })) {
    tool("close_issue", { id: issue.id });
    closed.push(issue.id);
  }
}
({ runId, closed })

